// arbitrage_checker.hpp#ifndef SPOTANDFUTURESARBITRAGE_ARBITRAGE_CHECKER_HPP#define SPOTANDFUTURESARBITRAGE_ARBITRAGE_CHECKER_HPP#include <iostream>#include "tick_handler.hpp"#include "db_connection.hpp"class arbitrage_checker{public:    static constexpr int64_t fee_scale = 1000000;    static constexpr int64_t spot_taker_fee_ppm = 1000;    static constexpr int64_t future_taker_fee_ppm = 400;    static constexpr int64_t slippage_buffer   = 5 * tick_handler::SCALE / 100;    static constexpr int64_t min_profit_margin = 10 * tick_handler::SCALE / 100;    static int64_t scaled_multiply(int64_t a, int64_t b)    {        __int128 result = static_cast<__int128>(a) * static_cast<__int128>(b);        result /= tick_handler::SCALE;        return static_cast<int64_t>(result);    }    static int64_t fee_cost(int64_t price, int64_t qty)    {        int64_t total_notional = scaled_multiply(price, qty);        return (total_notional * (spot_taker_fee_ppm + future_taker_fee_ppm)) / fee_scale;    }    static int64_t total_cost(int64_t price, int64_t qty)    {        return fee_cost(price, qty) + slippage_buffer + min_profit_margin;    }    static bool is_profitable(int64_t spread, int64_t price, int64_t qty)    {        int64_t gross_profit = scaled_multiply(spread, qty);        return gross_profit > total_cost(price, qty);    }    arbitrage_checker(tick_handler& spot_ticks, tick_handler& future_ticks, int64_t qty, const std::string table_name, db_connection& db_conn);    void check_for_arbitrage();private:    tick_handler& spot_ticks_;    tick_handler& future_ticks_;    db_connection& db_conn_;    int64_t qty_;     std::string table_name_;    void check_buy_spot_sell_future();    void check_sell_spot_buy_future();};#endif